    out = [[0] * out_w for _ in range(h)]

    marker = next((r, c - divider - 1)
                  for r, row in enumerate(grid)
                  for c, value in enumerate(row)
                  if value == 5 and c > divider)
    r, c = marker
    out[r][c] = 5

    moves = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): ("right", 3),
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): ("left", 2),
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): ("down", 2),
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): ("left", 4),
    }
    objects = []
    for col in (0, 4):
        for top in range(0, h, 4):
            patch = [row[col:col + 3] for row in grid[top:top + 3]]
            color = next((v for line in patch for v in line if v), 0)
            pattern = tuple(tuple(int(v == color) for v in line) for line in patch)
            objects.append((color, moves[pattern]))

    for color, (direction, length) in objects:
        if direction == "down":
            for rr in range(r + 1, r + length + 1):
                if 0 <= rr < h and 0 <= c < out_w:
                    out[rr][c] = color
